entries[10650] = { ["name"] = "Drachenschuppenbrustplatte", ["text"] = "Wirken in 2 sek.\nReagenzien:\nDickes Leder (40), Abgenutzte Drachenschuppe (30), Schwerer Seidenfaden (4), Geschmeidiger dicker Balg (4)\nOptionale Reagenzien:\n[] (#50)\nBerufsausbilder:\nKlassische Lederverarbeitung (255)\nKosten:\n21\n\nDrachenschuppenbrustplatte\nWird beim Anlegen gebunden\nBrust Kette\n9 Rüstung\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 5.\nHaltbarkeit 140 / 140\nBenutzen: Absorbiert 11 Magieschaden. Hält 2 Min. lang an. (1 Stunde Abklingzeit)\n20" }
